rtl:
always_comb
  unique case (1'b1)  // Fails when req is multi-hot
    req[0]: gnt = 4'h1;
    req[1]: gnt = 4'h2;
    req[2]: gnt = 4'h4;
    req[3]: gnt = 4'h8;
  endcase

fix_replacement:
always_comb begin
  gnt = 4'h0;
  priority case (1'b1)  // priority handles multi-hot correctly
    req[last_gnt[1:0]]:            gnt = 4'h1 << last_gnt;
    req[(last_gnt+1) % 4]:         gnt = 4'h1 << ((last_gnt+1) % 4);
    req[(last_gnt+2) % 4]:         gnt = 4'h1 << ((last_gnt+2) % 4);
    req[(last_gnt+3) % 4]:         gnt = 4'h1 << ((last_gnt+3) % 4);
  endcase
end
